Contract GenerateLoanLetterAndAgreementModule::generateLoanAgreement(): Boolean {

            precondition:
          CurrentLoanRequest.oclIsUndefined() = false

            postcondition:
          let newLoanAgreement:LoanAgreement in newLoanAgreement.oclIsNew() and newLoanAgreement.Content = "Loan Agreement" and LoanAgreement.allInstance()->includes(newLoanAgreement) and CurrentLoanRequest.AttachedLoanAgreement = newLoanAgreement and temp:Boolean = true and result = temp

        }
